import java.util.*;

public class Main {

    public static String readLn() {
        Scanner scanner = new Scanner(System.in);
        return scanner.nextLine();
    }

    public static int readInt() {
        return Integer.parseInt(readLn());
    }

    public static List<String> readStrings() {
        return Arrays.asList(readLn().split(" "));
    }

    public static List<Integer> readInts() {
        List<String> strings = readStrings();
        List<Integer> ints = new ArrayList<>();
        for (String s : strings) {
            ints.add(Integer.parseInt(s));
        }
        return ints;
    }

    public static int findLissPos() {
        String stones = readLn();
        String instructions = readLn();
        int curPos = 0;
        for (int i = 0; i < instructions.length(); i++) {
            if (stones.charAt(curPos) == instructions.charAt(i)) {
                curPos++;
            }
        }
        curPos++;
        return curPos;
    }

    public static void main(String[] args) {
        System.out.print(findLissPos());
    }
}

